const LOAD_TYPES={barbell:'Barbell · plates per side',dumbbell:'Dumbbells · each hand',stack:'Cable / pin stack · displayed weight',dual:'Dual cable · each stack',plate:'Plate-loaded machine · each side',total:'Total external load',bodyweight:'Bodyweight / added load'};
function loadType(name){let x=catalog.find(a=>a[0]===name),equip=x?.[2]||'';if(/EZ Bar|Bench Press$/.test(name)&&equip==='Barbell')return 'barbell';if(equip==='Barbell')return 'barbell';if(equip==='Dumbbells')return 'dumbbell';if(equip==='Cable')return /Cable Chest Fly/i.test(name)?'dual':'stack';if(equip==='Machine')return /Leg Press|Incline Chest Press/i.test(name)?'plate':'stack';if(equip==='Bodyweight')return 'bodyweight';return 'total'}
function loadConfig(e){return {type:e.loadType||loadType(e.name),bar:Number.isFinite(+e.barWeight)?+e.barWeight:20,base:Number.isFinite(+e.machineBase)?+e.machineBase:0,arms:e.armCount===1?1:2}}
