function loadEntryLabel(c){return {barbell:'PLATES PER SIDE',plate:'PLATES PER SIDE',dumbbell:c.arms===1?'WEIGHT PER DUMBBELL (SINGLE ARM)':'WEIGHT PER DUMBBELL',dual:'WEIGHT PER CABLE STACK',stack:'DISPLAYED STACK WEIGHT',total:'TOTAL EXTERNAL LOAD',bodyweight:'ADDED LOAD (KG)'}[c.type]}
