function smartLoadUI(e,prev){let c=loadConfig(e),legacyPrevious=prev?.kg!=null&&!prev?.load&&!e.logged.length&&e.nextLoad==null,kg=legacyPrevious?NaN:nextLoad(e,prev,c),input=Number.isFinite(kg)?(e.nextLoad!=null?inputFromTotal(kg,c):safeSetInput(prev,c)):'',selected=e.loadType||loadType(e.name),note=c.type==='stack'||c.type==='plate'?'Machine loads are tracking conventions, not measured handle force.':'';
return `<div class="smart-load"><div class="smart-load-title"><b>⚡ SMART LOAD</b><small>Exercise-specific resistance</small></div><label>LOAD METHOD<select id="loadType" onchange="changeLoadType(this.value)">${Object.entries(LOAD_TYPES).map(([k,v])=>`<option value="${k}" ${selected===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="smart-load-grid"><label>${loadEntryLabel(c)}<input id="kg" class="big" type="number" min="0" step="0.5" value="${esc(input)}" placeholder="0.0" inputmode="decimal" oninput="updateSmartTotal()"><div class="step-controls">${btn('−',"adjust('kg',-2.5);updateSmartTotal()")}${btn('+',"adjust('kg',2.5);updateSmartTotal()")}</div></label><div class="smart-load-total"><small>CALCULATED LOAD</small><strong id="smartTotal">${Number.isFinite(kg)?kg.toFixed(1):'—'} kg</strong><small>used for volume</small></div></div>${c.type==='barbell'?`<label>BAR WEIGHT (KG)<input id="barWeight" type="number" min="0" step="0.5" value="${c.bar}" onchange="changeLoadExtra('barWeight',this.value)"></label>`:''}${c.type==='plate'?`<label>MACHINE STARTING RESISTANCE (KG)<input id="machineBase" type="number" min="0" step="0.5" value="${c.base}" onchange="changeLoadExtra('machineBase',this.value)"></label>`:''}${c.type==='dumbbell'?`<label>NUMBER OF DUMBBELLS<select id="armCount" onchange="changeLoadExtra('armCount',this.value)"><option value="2" ${c.arms===2?'selected':''}>Two dumbbells</option><option value="1" ${c.arms===1?'selected':''}>One dumbbell / unilateral</option></select></label>`:''}${legacyPrevious?'<small class="muted">Previous weight was recorded before Smart Load. Enter the correct per-side or per-dumbbell load; old records are unchanged.</small>':''}${note?`<small class="muted">${note}</small>`:''}</div>`}
function updateSmartTotal(){let e=state.draft?.ex[index];if(!e)return;let v=actualLoad($('kg')?.value,loadConfig(e));let t=$('smartTotal');if(t)t.textContent=Number.isFinite(v)?v.toFixed(1)+' kg':'—'}
