function confirmLowerLoad(){let e=state.draft.ex[index],n=Number($('lowerTotal').value),reason=$('lowerReason').value;if($('lowerTotal').value===''||!Number.isFinite(n)||n<0)return alert('Enter a valid load');e.nextLoad=n;e.lastAdjustmentReason=reason;save();closeModal();render();if(reason==='pain')alert('Pain or discomfort recorded. Stop the painful movement and reassess rather than pushing through pain.')}
