 if(!state.draft)return '<h1>No active workout</h1>'+btn('Select workout',"go('train')");
 let d=state.draft;index=Math.max(0,Math.min(index,d.ex.length-1));let e=d.ex[index],p=last(e.name),prev=e.logged.at(-1)||p[e.logged.length]||p.at(-1)||{},target=String(e.reps).match(/\d+/g)||['10'],top=+target.at(-1),suggest=p.length&&p.length>=e.sets&&p.every(s=>s.reps>=top)?Number(p[0].kg)+2.5:null,done=d.ex.reduce((a,x)=>a+x.logged.length,0),total=d.ex.reduce((a,x)=>a+Number(x.sets),0);
